                # Check if this could be L corner
                # L extends vertically from row 0 down to r
                vertical_ok = all(grid[i][c] == l_color for i in range(r+1))
                # L extends horizontally from col 0 to c
                horizontal_ok = all(grid[r][j] == l_color for j in range(c))

                if vertical_ok and horizontal_ok:
                    corner_row = r
                    corner_col = c
                    break
        if corner_row is not None:
            break

    if corner_col is None:
        return output  # No L found, return as-is

    # Calculate new cell positions
    new_count = max(1, corner_row // 2)

    # Generate positions following the observed pattern
    positions = [(0, 0)]  # First cell
    # Add more cells based on pattern
